import React, { forwardRef, ReactNode } from 'react';
import { isElement } from 'react-is';

import { ACTION_GROUP_GAP } from './ActionGroup.js';
import { useActionGroupContext } from './hooks/useActionGroupContext.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Menu } from '../../../navigation/menu/Menu.js';

// #region Typings
// ESLint disabled in order for API extractor not to complain about exporting
// With children from the package
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface GroupProps extends WithChildren, StylingProps, DataTestId {}

type SlotsType = {
  items: ReactNode[];
};
// #endregion

/**
 * A group of action items.
 * A horizontal / vertical divider will be rendered between grouped actions.
 */
export const Group = forwardRef<HTMLDivElement, GroupProps>(
  (props, forwardedRef) => {
    const {
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: GroupProps = props;

    const slots: SlotsType = {
      items: [],
    };

    for (const child of React.Children.toArray(children)) {
      if (isElement(child)) {
        slots.items?.push(child);
      }
    }

    const { isCollapsed } = useActionGroupContext();

    return isCollapsed ? (
      <Menu.Group
        ref={forwardedRef}
        className={consumerClassName}
        style={consumerStyle}
        data-testid={dataTestId}
      >
        {slots.items}
      </Menu.Group>
    ) : (
      <Flex
        ref={forwardedRef}
        gap={ACTION_GROUP_GAP}
        alignItems="center"
        role="group"
        className={consumerClassName}
        style={consumerStyle}
        data-testid={dataTestId}
        {...remainingProps}
      >
        {slots.items}
      </Flex>
    );
  },
);

(Group as typeof Group & { displayName: string }).displayName =
  'ActionGroup.Group';
